<?php

declare(strict_types=1);

require_once __DIR__ . '/_context.php';
require_once __DIR__ . '/../../src/Services/PlatformTenantLifecycle.php';
[, , , $identity, $service] = requireAuthorizedPlatformContext();
$query=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$limit=max(1,min(100,(int)($_GET['limit']??20)));$statusFilter=(string)($_GET['status']??'');$result=$service->searchTenants($identity,$query,$page,$limit,$statusFilter);$tenants=$result['items'];$total=(int)$result['total'];$from=$total?($page-1)*$limit+1:0;$to=min($total,$page*$limit);
$lifecycle = new \MiniErp\Services\PlatformTenantLifecycle();
if (empty($_SESSION['platform_logout_csrf'])) $_SESSION['platform_logout_csrf'] = bin2hex(random_bytes(32));

$metrics = ['total' => count($tenants), 'active' => 0, 'pending' => 0, 'blocked' => 0];
foreach ($tenants as $item) {
    $state = $lifecycle->interpret((string) ($item['status'] ?? ''), !empty($item['blocked']));
    if ($state === 'ativa') $metrics['active']++;
    if ($state === 'cadastrada') $metrics['pending']++;
    if (in_array($state, ['parcialmente_bloqueada', 'bloqueada'], true)) $metrics['blocked']++;
}
$escape = static fn (mixed $value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$statusLabel = static fn (string $state): string => match ($state) { 'cadastrada' => 'Cadastrada', 'provisionando' => 'Provisionando', 'ativa' => 'Ativa', 'parcialmente_bloqueada' => 'Bloqueio parcial', 'bloqueada' => 'Bloqueada', 'arquivada' => 'Arquivada', default => 'Estado desconhecido' };
$statusClass = static fn (string $state): string => match ($state) { 'cadastrada' => 'badge-pending', 'provisionando' => 'badge-running', 'ativa' => 'badge-active', 'parcialmente_bloqueada', 'bloqueada' => 'badge-blocked', 'arquivada' => 'badge-archived', default => 'badge-unknown' };
$_SESSION['platform_erp_access_csrf'] ??= bin2hex(random_bytes(32));
$erpAccessUrl = static fn (int $tenantId): string => '/plataforma/empresa-acao.php?id=' . $tenantId . '&amp;action=erp&amp;csrf_token=' . rawurlencode((string) $_SESSION['platform_erp_access_csrf']);
?>
