<section class="cards" aria-label="Resumo"><article class="stat-card"><span>Empresas nesta página</span><strong><?= $metrics['total'] ?></strong></article><article class="stat-card"><span>Empresas ativas</span><strong><?= $metrics['active'] ?></strong></article><article class="stat-card"><span>Aguardando provisionamento</span><strong><?= $metrics['pending'] ?></strong></article><article class="stat-card"><span>Empresas bloqueadas</span><strong><?= $metrics['blocked'] ?></strong></article></section>
<section class="panel"><div class="panel-header"><div><h2>Empresas da plataforma</h2><span class="muted">A disponibilidade das ações segue o lifecycle.</span></div></div><div class="table-wrap company-mobile-wrap"><table class="platform-company-table"><thead><tr><th>Empresa</th><th>CNPJ</th><th>Tenant</th><th>Slug</th><th>Status</th><th>Ambiente</th><th>Ações</th></tr></thead><tbody>
<?php foreach ($tenants as $tenant): $state = $lifecycle->interpret((string) ($tenant['status'] ?? ''), !empty($tenant['blocked'])); $actions = $lifecycle->actions((string) ($tenant['status'] ?? ''), $tenant['db_name'] ?? null, !empty($tenant['blocked'])); $tenantId = (int) ($tenant['tenant_id'] ?? 0); ?>
<tr data-company-row="<?= $tenantId ?>"><td class="company-name" data-label="Empresa"><strong><?php if($actions['erp']):?><a class="company-name-login" href="<?= $erpAccessUrl($tenantId) ?>"><?= $escape($tenant['nome_fantasia'] ?? '') ?></a><?php else:?><?= $escape($tenant['nome_fantasia'] ?? '') ?><?php endif;?></strong><small><?= $escape($tenant['razao_social'] ?? '') ?></small><?php if($actions['erp']):?><a class="mobile-company-login" href="<?= $erpAccessUrl($tenantId) ?>"><span aria-hidden="true">→</span> Entrar na empresa</a><?php else:?><span class="mobile-company-login disabled" aria-disabled="true">Empresa indisponível</span><?php endif;?></td><td data-label="CNPJ"><?= $escape($tenant['cnpj'] ?? '') ?></td><td data-label="Tenant">#<?= $tenantId ?></td><td data-label="Slug"><?= $escape($tenant['slug'] ?? '') ?></td><td data-label="Status"><span class="badge <?= $statusClass($state) ?>"><?= $statusLabel($state) ?></span></td><td class="environment" data-label="Ambiente"><?= trim((string) ($tenant['db_name'] ?? '')) !== '' ? 'Banco dedicado disponível' : 'Não provisionado' ?></td><td class="company-action-cell" data-label="Ações"><div class="actions company-mobile-actions"><a class="btn small secondary" data-company-database="<?= \MiniErp\Authorization\PlatformDatabaseAccess::canView($identity,$tenant)?'1':'0' ?>" data-company-modal data-company-id="<?= $tenantId ?>" data-company-name="<?= $escape($tenant['nome_fantasia'] ?: $tenant['razao_social']) ?>" href="/plataforma/empresa.php?id=<?= $tenantId ?>">Editar</a><?php if ($actions['provision']): ?><a class="btn small" href="/plataforma/empresa-provisionar.php?id=<?= $tenantId ?>">Provisionar</a><?php else: ?><span class="btn small disabled" aria-disabled="true">Provisionar</span><?php endif; ?><?php if ($actions['users']): ?><a class="btn small ghost" href="/plataforma/empresa-acao.php?id=<?= $tenantId ?>&amp;action=usuarios">Usuários</a><?php else: ?><span class="btn small disabled" aria-disabled="true" title="Disponível após configuração">Usuários</span><?php endif; ?><?php if ($actions['erp']): ?><a class="btn small mobile-erp-button" href="<?= $erpAccessUrl($tenantId) ?>">Acessar ERP</a><?php else: ?><span class="btn small disabled" aria-disabled="true" title="Disponível após configuração">Acessar ERP</span><?php endif; ?></div></td></tr>
<?php endforeach; ?><?php if ($tenants === []): ?><tr><td colspan="7">Nenhuma empresa cadastrada.</td></tr><?php endif; ?></tbody></table></div><nav class="actions" aria-label="Paginação"><?php $pages=max(1,(int)ceil($total/$limit));$base='?q='.rawurlencode($query).'&status='.rawurlencode($statusFilter).'&limit='.$limit.'&page=';?><?php if($page>1):?><a class="btn secondary" href="<?=$base.($page-1)?>">Anterior</a><?php endif;?><span>Página <?=$page?> de <?=$pages?></span><?php if($page<$pages):?><a class="btn secondary" href="<?=$base.($page+1)?>">Próxima</a><?php endif;?></nav></section><footer class="site-credit platform-credit">Desenvolvido por <a href="https://willspacce.netlify.app/" target="_blank" rel="noopener noreferrer" aria-label="Portfólio de Willyan Martins">Willyan Martins <span aria-hidden="true">›</span></a></footer></main></div></div></body></html>
